function iso(d) { return d.toISOString().slice(0, 10); }
function tageVorHeute(n) {
  const d = new Date();
  d.setUTCHours(0, 0, 0, 0);
  d.setUTCDate(d.getUTCDate() - n);
  return iso(d);
}

// Die Zustelldaten sind relativ zu HEUTE gesetzt, damit der Test bei jedem
