// =====================================================================
//  Fristberechnung § 840 ZPO  +  Ermittlung des Handlungsbedarfs
//
//  Regeln:
//   - Frist = Zustelldatum + 14 KALENDERtage (nicht Arbeitstage).
//   - Faellt das Fristende auf Samstag, Sonntag oder Feiertag, verschiebt
//     es sich auf den naechsten Werktag (§ 222 Abs. 2 ZPO i.V.m. § 193 BGB).
//   - Erinnerung 1 am Tag des Fristbeginns.
//   - Erinnerung 2 drei Kalendertage vor Fristende.
//   - Eskalation an Vorgesetzte + Vertretung einen Tag vor Fristende.
//   - Alles nur, solange die Erklaerung noch nicht versandt ist.
//   - Bereits gesendete Erinnerungen werden nicht wiederholt (Idempotenz).
// =====================================================================

const FRIST_TAGE = 14;
const VORLAUF_ERINNERUNG_2 = 3;
const VORLAUF_ESKALATION = 1;
const STATUS_ERLEDIGT = ['Erklaerung versandt', 'Abgeschlossen', 'Abgeschlossen mit Fristversaeumnis'];

// Feiertage bitte pflegen — hier beispielhaft die bundeseinheitlichen 2026.
const FEIERTAGE = [
  '2026-01-01', '2026-04-03', '2026-04-06', '2026-05-01',
  '2026-05-14', '2026-05-25', '2026-10-03', '2026-12-25', '2026-12-26',
];

function toDate(s) { return new Date(s.slice(0, 10) + 'T00:00:00Z'); }
function iso(d) { return d.toISOString().slice(0, 10); }
function addDays(d, n) { const x = new Date(d); x.setUTCDate(x.getUTCDate() + n); return x; }
function istWerktag(d) {
  const wd = d.getUTCDay();
  return wd !== 0 && wd !== 6 && !FEIERTAGE.includes(iso(d));
}
function naechsterWerktag(d) { let x = new Date(d); while (!istWerktag(x)) x = addDays(x, 1); return x; }
function tageDiff(a, b) { return Math.round((a.getTime() - b.getTime()) / 86400000); }

const heute = new Date();
heute.setUTCHours(0, 0, 0, 0);

const out = [];

for (const item of $input.all()) {
  const f = item.json;

  const zustellung = toDate(f.zustelldatum);
  const fristRoh = addDays(zustellung, FRIST_TAGE);
  const frist = naechsterWerktag(fristRoh);
  const restTage = tageDiff(frist, heute);

  const gesendet = Array.isArray(f.erinnerungen_gesendet) ? f.erinnerungen_gesendet : [];
  const erledigt = STATUS_ERLEDIGT.includes(f.status);

  let aktion = 'keine';
  let begruendung = '';

  if (erledigt) {
    aktion = 'keine';
    begruendung = 'Erklaerung bereits versandt — Fristueberwachung fuer diesen Fall beendet.';
  } else if (restTage < 0) {
    aktion = 'fristversaeumnis';
    begruendung = `Frist am ${iso(frist)} abgelaufen, Erklaerung nicht versandt.`;
  } else if (restTage <= VORLAUF_ESKALATION && !gesendet.includes('eskalation')) {
    aktion = 'eskalation';
    begruendung = `Noch ${restTage} Tag(e) bis Fristablauf, Erklaerung offen.`;
  } else if (restTage <= VORLAUF_ERINNERUNG_2 && !gesendet.includes('erinnerung_2')) {
    aktion = 'erinnerung_2';
    begruendung = `Noch ${restTage} Tag(e) bis Fristablauf.`;
  } else if (!gesendet.includes('erinnerung_1')) {
    aktion = 'erinnerung_1';
    begruendung = 'Fristbeginn — Fall zur Bearbeitung eingesteuert.';
  } else {
    aktion = 'keine';
    begruendung = `Noch ${restTage} Tag(e) Puffer, faellige Erinnerung bereits versandt.`;
  }

  out.push({
    json: {
      ...f,
      fristende_roh: iso(fristRoh),
      fristende: iso(frist),
      fristende_verschoben: iso(frist) !== iso(fristRoh),
      rest_tage: restTage,
      heute: iso(heute),
      aktion,
      begruendung,
    },
  });
}

return out;

